import React, { useState, useEffect } from "react";
import { Modal, Button } from "antd";
import {
  MobileOutlined,
  DownloadOutlined,
  ShareAltOutlined,
  PlusSquareOutlined,
} from "@ant-design/icons";
import MatrimonyLogoIcon from "./MatrimonyLogoIcon";

/**
 * PwaInstallButton
 * Strictly Mobile Only ("WPA is for only Mobile dont give orshow option for window").
 * Allows mobile users to add वैवाहिक मंच to their phone's home screen as a native-like app.
 */
export default function PwaInstallButton({
  variant = "menu", // 'menu' | 'footer' | 'pill'
  style = {},
  className = "",
}) {
  const [deferredPrompt, setDeferredPrompt] = useState(null);
  const [isMobileDevice, setIsMobileDevice] = useState(false);
  const [isInstalled, setIsInstalled] = useState(false);
  const [isIosModalOpen, setIsIosModalOpen] = useState(false);

  useEffect(() => {
    // 1. Check if strictly mobile device (Android, iPhone, iPad, or viewport <= 768px with touch)
    const checkMobile = () => {
      const ua = navigator.userAgent || "";
      const isMobileUA = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(ua);
      const isSmallTouchScreen = (window.innerWidth <= 768 && ("ontouchstart" in window || navigator.maxTouchPoints > 0));
      return isMobileUA || isSmallTouchScreen;
    };

    setIsMobileDevice(checkMobile());

    // 2. Check if already installed / running in standalone PWA mode
    const checkStandalone = () => {
      return (
        window.matchMedia("(display-mode: standalone)").matches ||
        window.navigator.standalone === true
      );
    };

    if (checkStandalone()) {
      setIsInstalled(true);
    }

    // 3. Listen to browser beforeinstallprompt (Android / Chrome mobile)
    const handleBeforeInstall = (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };

    window.addEventListener("beforeinstallprompt", handleBeforeInstall);

    const handleAppInstalled = () => {
      setIsInstalled(true);
      setDeferredPrompt(null);
    };

    window.addEventListener("appinstalled", handleAppInstalled);

    return () => {
      window.removeEventListener("beforeinstallprompt", handleBeforeInstall);
      window.removeEventListener("appinstalled", handleAppInstalled);
    };
  }, []);

  // Strictly do NOT render on Windows / Desktop
  if (!isMobileDevice || isInstalled) {
    return null;
  }

  const handleInstallClick = async (e) => {
    if (e && e.preventDefault) e.preventDefault();

    // Android / Chrome with prompt event
    if (deferredPrompt) {
      deferredPrompt.prompt();
      const choiceResult = await deferredPrompt.userChoice;
      if (choiceResult.outcome === "accepted") {
        setIsInstalled(true);
      }
      setDeferredPrompt(null);
      return;
    }

    // iOS Safari or mobile browsers without prompt event -> open guided install modal
    setIsIosModalOpen(true);
  };

  // Render variant: Homepage Footer
  if (variant === "footer") {
    return (
      <>
        <div
          className={`vm-pwa-footer-box ${className}`}
          onClick={handleInstallClick}
          style={{
            background: "linear-gradient(135deg, #be185d 0%, #db2777 50%, #f43f5e 100%)",
            borderRadius: "18px",
            padding: "16px 20px",
            color: "#ffffff",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            gap: "14px",
            cursor: "pointer",
            boxShadow: "0 8px 24px rgba(219, 39, 119, 0.3)",
            border: "1.5px solid rgba(254, 240, 138, 0.4)",
            margin: "20px auto 10px auto",
            maxWidth: "460px",
            width: "100%",
            ...style,
          }}
        >
          <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
            <div
              style={{
                width: "44px",
                height: "44px",
                borderRadius: "12px",
                background: "rgba(255, 255, 255, 0.15)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                flexShrink: 0,
                border: "1px solid rgba(255, 255, 255, 0.3)",
              }}
            >
              <MatrimonyLogoIcon size={26} />
            </div>
            <div>
              <div style={{ fontWeight: 900, fontSize: "15px", letterSpacing: "-0.2px" }}>
                वैवाहिक मंच ऐप इंस्टॉल करें
              </div>
              <div style={{ fontSize: "11px", color: "#fef08a", fontWeight: 700 }}>
                📱 Add to Mobile Home Screen for Quick Access
              </div>
            </div>
          </div>

          <Button
            type="primary"
            size="small"
            icon={<DownloadOutlined />}
            style={{
              background: "#ffffff",
              color: "#881337",
              borderColor: "transparent",
              fontWeight: 800,
              borderRadius: "20px",
              height: "32px",
              padding: "0 14px",
              fontSize: "12px",
              boxShadow: "0 2px 8px rgba(0,0,0,0.15)",
              flexShrink: 0,
            }}
          >
            Install
          </Button>
        </div>

        {/* iOS Guided Modal */}
        <IosInstallModal
          open={isIosModalOpen}
          onClose={() => setIsIosModalOpen(false)}
        />
      </>
    );
  }

  // Default: Side menu / drawer near Homepage button
  return (
    <>
      <div
        className={`vm-pwa-menu-item ${className}`}
        onClick={handleInstallClick}
        style={{
          background: "linear-gradient(135deg, #fdf2f8 0%, #fce7f3 100%)",
          border: "1.5px solid #fbcfe8",
          borderRadius: "14px",
          padding: "10px 14px",
          margin: "8px 0 14px 0",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          cursor: "pointer",
          gap: "10px",
          boxShadow: "0 2px 8px rgba(219, 39, 119, 0.08)",
          ...style,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
          <div
            style={{
              width: "32px",
              height: "32px",
              borderRadius: "10px",
              background: "linear-gradient(135deg, #be185d, #db2777)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              color: "#ffffff",
              flexShrink: 0,
            }}
          >
            <MobileOutlined style={{ fontSize: "16px" }} />
          </div>
          <div>
            <div style={{ fontWeight: 800, fontSize: "13px", color: "#9d174d" }}>
              ऐप डाउनलोड / होम स्क्रीन
            </div>
            <div style={{ fontSize: "10px", color: "#db2777", fontWeight: 700 }}>
              Add App to Phone
            </div>
          </div>
        </div>

        <span
          style={{
            background: "linear-gradient(135deg, #ec4899, #db2777)",
            color: "#ffffff",
            fontSize: "10.5px",
            fontWeight: 800,
            padding: "3px 9px",
            borderRadius: "12px",
            boxShadow: "0 2px 6px rgba(219, 39, 119, 0.25)",
          }}
        >
          Add 📲
        </span>
      </div>

      <IosInstallModal
        open={isIosModalOpen}
        onClose={() => setIsIosModalOpen(false)}
      />
    </>
  );
}

// Guided Step-by-Step Sheet for iOS Safari / Mobile Browsers
function IosInstallModal({ open, onClose }) {
  return (
    <Modal
      open={open}
      onCancel={onClose}
      footer={[
        <Button
          key="done"
          type="primary"
          onClick={onClose}
          style={{
            borderRadius: "14px",
            fontWeight: 800,
            background: "linear-gradient(135deg, #db2777, #be185d)",
            borderColor: "transparent",
            width: "100%",
            height: "40px",
          }}
        >
          Got It / ठीक है
        </Button>,
      ]}
      centered
      width={380}
      title={null}
    >
      <div style={{ textAlign: "center", padding: "10px 4px" }}>
        <div style={{ display: "inline-flex", justifyContent: "center", marginBottom: "8px" }}>
          <MatrimonyLogoIcon size={44} />
        </div>
        <h3 style={{ margin: "4px 0", fontSize: "17px", fontWeight: 900, color: "#9d174d" }}>
          वैवाहिक मंच फोन में इंस्टॉल करें
        </h3>
        <p style={{ fontSize: "12px", color: "#64748b", margin: "0 0 16px 0" }}>
          Add Vaivaheek Manch to your Phone Home Screen
        </p>

        <div style={{ textAlign: "left", background: "#f8fafc", padding: "14px 16px", borderRadius: "14px", border: "1px solid #e2e8f0" }}>
          <div style={{ display: "flex", gap: "10px", alignItems: "flex-start", marginBottom: "12px" }}>
            <span style={{ background: "#fee2e2", color: "#991b1b", width: "24px", height: "24px", borderRadius: "50%", display: "inline-flex", alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: "12px", flexShrink: 0 }}>
              1
            </span>
            <div style={{ fontSize: "12.5px", color: "#1e293b", lineHeight: "1.4" }}>
              ब्राउज़र के नीचे <strong>Share</strong> ( <ShareAltOutlined style={{ color: "#2563eb" }} /> या ⎋ ) बटन पर टैप करें।
            </div>
          </div>

          <div style={{ display: "flex", gap: "10px", alignItems: "flex-start", marginBottom: "12px" }}>
            <span style={{ background: "#fee2e2", color: "#991b1b", width: "24px", height: "24px", borderRadius: "50%", display: "inline-flex", alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: "12px", flexShrink: 0 }}>
              2
            </span>
            <div style={{ fontSize: "12.5px", color: "#1e293b", lineHeight: "1.4" }}>
              नीचे स्क्रॉल करके <strong>'Add to Home Screen'</strong> ( <PlusSquareOutlined style={{ color: "#059669" }} /> ) चुनें।
            </div>
          </div>

          <div style={{ display: "flex", gap: "10px", alignItems: "flex-start" }}>
            <span style={{ background: "#fee2e2", color: "#991b1b", width: "24px", height: "24px", borderRadius: "50%", display: "inline-flex", alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: "12px", flexShrink: 0 }}>
              3
            </span>
            <div style={{ fontSize: "12.5px", color: "#1e293b", lineHeight: "1.4" }}>
              ऊपर दाईं ओर <strong>'Add'</strong> पर टैप करें। वैवाहिक मंच आपके फोन स्क्रीन पर आ जाएगा!
            </div>
          </div>
        </div>
      </div>
    </Modal>
  );
}

