import React, { useEffect } from "react";

/**
 * AntiScreenshotShield
 * Comprehensive silent screen capture, print, and copy protection.
 * Protects profiles, photographs, and wedding service details without intrusive warning messages.
 */
export default function AntiScreenshotShield() {
  useEffect(() => {
    // 1. Wipe clipboard silently when PrintScreen is triggered
    const handleKeyUp = (e) => {
      const keyName = String(e.key || e.code || "").toLowerCase();
      if (keyName.includes("printscreen") || e.keyCode === 44) {
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText("").catch(() => {});
        }
      }
    };

    // 2. Intercept keyboard shortcuts silently (Ctrl+P, Ctrl+S, Ctrl+Shift+S, Cmd+Shift+3/4/5, F12, DevTools)
    const handleKeyDown = (e) => {
      const isCmdOrCtrl = e.ctrlKey || e.metaKey;
      const key = String(e.key || "").toLowerCase();

      // F12 key (Inspect DevTools)
      if (e.key === "F12" || e.keyCode === 123) {
        e.preventDefault();
        e.stopPropagation();
        return false;
      }

      // DevTools inspect shortcuts (Ctrl+Shift+I, Ctrl+Shift+J, Ctrl+Shift+C)
      if (isCmdOrCtrl && e.shiftKey && ["i", "j", "c"].includes(key)) {
        e.preventDefault();
        e.stopPropagation();
        return false;
      }

      // View Source (Ctrl + U)
      if (isCmdOrCtrl && key === "u") {
        e.preventDefault();
        e.stopPropagation();
        return false;
      }

      // Mac screenshot shortcuts (Cmd + Shift + 3 / 4 / 5)
      if (e.metaKey && e.shiftKey && ["3", "4", "5"].includes(key)) {
        e.preventDefault();
        e.stopPropagation();
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText("").catch(() => {});
        }
        return false;
      }

      // Print page shortcut (Ctrl + P / Cmd + P)
      if (isCmdOrCtrl && key === "p") {
        e.preventDefault();
        e.stopPropagation();
        return false;
      }

      // Save page shortcut (Ctrl + S / Cmd + S) outside active input fields
      if (isCmdOrCtrl && key === "s" && !e.shiftKey) {
        const tag = (e.target?.tagName || "").toLowerCase();
        if (tag !== "input" && tag !== "textarea") {
          e.preventDefault();
          e.stopPropagation();
          return false;
        }
      }

      // Windows / Firefox Snipping shortcut (Ctrl + Shift + S)
      if (isCmdOrCtrl && e.shiftKey && key === "s") {
        e.preventDefault();
        e.stopPropagation();
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText("").catch(() => {});
        }
        return false;
      }
    };

    // 3. Mobile 3-finger swipe screenshot gesture detection
    const handleTouchStart = (e) => {
      if (e.touches && e.touches.length >= 3) {
        e.preventDefault();
      }
    };

    // 4. Anti-Snipping & App Switcher Shield (Window blur or visibility change)
    // Instantly blurs sensitive content if window loses focus or document is hidden
    const handleWindowBlur = () => {
      document.body.classList.add("vm-screen-shield-active");
    };

    const handleWindowFocus = () => {
      document.body.classList.remove("vm-screen-shield-active");
    };

    const handleVisibilityChange = () => {
      if (document.hidden) {
        document.body.classList.add("vm-screen-shield-active");
      } else {
        document.body.classList.remove("vm-screen-shield-active");
      }
    };

    // 5. Prevent right-click context menu on images and profile cards silently
    const handleContextMenu = (e) => {
      const sensitiveEl = e.target.closest(
        "img, .up-cand-card, .up-service-card, .up-service-h-card, .up-biodata-modal, .up-service-biodata-view, .ant-image-preview"
      );
      if (sensitiveEl) {
        e.preventDefault();
        return false;
      }
    };

    // 6. Prevent dragging photos out to desktop / new tab silently
    const handleDragStart = (e) => {
      if (e.target && e.target.tagName === "IMG") {
        e.preventDefault();
        return false;
      }
    };

    window.addEventListener("touchstart", handleTouchStart, { passive: false });
    window.addEventListener("keyup", handleKeyUp);
    window.addEventListener("keydown", handleKeyDown);
    window.addEventListener("blur", handleWindowBlur);
    window.addEventListener("focus", handleWindowFocus);
    document.addEventListener("visibilitychange", handleVisibilityChange);
    document.addEventListener("contextmenu", handleContextMenu);
    document.addEventListener("dragstart", handleDragStart);

    return () => {
      window.removeEventListener("touchstart", handleTouchStart);
      window.removeEventListener("keyup", handleKeyUp);
      window.removeEventListener("keydown", handleKeyDown);
      window.removeEventListener("blur", handleWindowBlur);
      window.removeEventListener("focus", handleWindowFocus);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
      document.removeEventListener("contextmenu", handleContextMenu);
      document.removeEventListener("dragstart", handleDragStart);
      document.body.classList.remove("vm-screen-shield-active");
    };
  }, []);

  return null;
}
