// =============================================================================
// SECURE STORAGE UTILITY FOR VAIVAHEEK MANCH
// Automatically encodes data before storing into window.localStorage
// and automatically decodes data upon retrieval from window.localStorage.
// Backward-compatible with existing plaintext keys.
// =============================================================================

const ENCODE_PREFIX = "__vm_enc__:";

/**
 * Encodes a string or JSON-serializable value into safe base64 with prefix.
 */
export const encodeStorageValue = (val) => {
  if (val === null || val === undefined) return val;
  try {
    const str = typeof val === "string" ? val : JSON.stringify(val);
    // Encode URI component first to safely support UTF-8 / Hindi / unicode characters
    return ENCODE_PREFIX + btoa(encodeURIComponent(str));
  } catch (err) {
    try {
      return ENCODE_PREFIX + btoa(unescape(encodeURIComponent(String(val))));
    } catch {
      return val;
    }
  }
};

/**
 * Decodes an encoded localStorage string back to its original plain value.
 * If the value was stored in plaintext (legacy), returns it as-is.
 */
export const decodeStorageValue = (val) => {
  if (val === null || val === undefined) return val;
  if (typeof val !== "string") return val;
  if (val.startsWith(ENCODE_PREFIX)) {
    const payload = val.slice(ENCODE_PREFIX.length);
    try {
      return decodeURIComponent(atob(payload));
    } catch (err) {
      try {
        return decodeURIComponent(escape(atob(payload)));
      } catch {
        try {
          return atob(payload);
        } catch {
          return val;
        }
      }
    }
  }
  // Fallback for legacy plaintext entries
  return val;
};

// Directly callable helper methods
export const setSecureItem = (key, value) => {
  if (typeof window === "undefined" || !window.localStorage) return;
  try {
    const encoded = encodeStorageValue(value);
    Storage.prototype.setItem.call(window.localStorage, key, encoded);
  } catch (e) {
    console.warn("secureStorage set error:", e);
  }
};

export const getSecureItem = (key) => {
  if (typeof window === "undefined" || !window.localStorage) return null;
  try {
    const raw = Storage.prototype.getItem.call(window.localStorage, key);
    return decodeStorageValue(raw);
  } catch (e) {
    return null;
  }
};

export const removeSecureItem = (key) => {
  if (typeof window === "undefined" || !window.localStorage) return;
  try {
    Storage.prototype.removeItem.call(window.localStorage, key);
  } catch (e) {
    // ignore
  }
};

// =============================================================================
// GLOBAL INTERCEPTOR: Monkey-patch Storage.prototype
// This ensures ANY call to localStorage.setItem(...) or localStorage.getItem(...)
// anywhere in the entire codebase automatically encodes on write and decodes on read.
// =============================================================================
(function installSecureStorageInterceptor() {
  if (typeof window === "undefined" || !window.Storage) return;

  const rawSetItem = Storage.prototype.setItem;
  const rawGetItem = Storage.prototype.getItem;

  // Intercept setItem to encode data before persisting
  Storage.prototype.setItem = function (key, value) {
    try {
      const encoded = encodeStorageValue(value);
      return rawSetItem.call(this, key, encoded);
    } catch (e) {
      return rawSetItem.call(this, key, value);
    }
  };

  // Intercept getItem to decode data before returning to callers
  Storage.prototype.getItem = function (key) {
    try {
      const raw = rawGetItem.call(this, key);
      return decodeStorageValue(raw);
    } catch (e) {
      return rawGetItem.call(this, key);
    }
  };

  // In-place upgrade of existing localStorage items to encoded format
  try {
    if (window.localStorage && window.localStorage.length > 0) {
      for (let i = 0; i < window.localStorage.length; i++) {
        const k = window.localStorage.key(i);
        if (k) {
          const current = rawGetItem.call(window.localStorage, k);
          if (current && typeof current === "string" && !current.startsWith(ENCODE_PREFIX)) {
            rawSetItem.call(window.localStorage, k, encodeStorageValue(current));
          }
        }
      }
    }
  } catch (migrationErr) {
    // Non-blocking in restricted iframe / sandbox contexts
  }
})();

const secureStorage = {
  encode: encodeStorageValue,
  decode: decodeStorageValue,
  getItem: getSecureItem,
  setItem: setSecureItem,
  removeItem: removeSecureItem,
};

export default secureStorage;

